<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Support\LegacyResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Throwable;
class DashboardController extends Controller
{
 public function summary(Request $r){try{$eq=DB::table('equipment')->where('active',true);if($r->filled('plant'))$eq->where('plant',$r->input('plant'));$total=(clone $eq)->count();$running=(clone $eq)->where('current_status','RUNNING')->count();$stopped=(clone $eq)->where('current_status','STOPPED')->count();$avail=['total'=>$total,'running'=>$running,'stopped'=>$stopped,'availability_pct'=>$total?round($running/$total*100,1):null];$b=DB::table('breakdowns as b')->join('equipment as e','e.id','=','b.equipment_id');if($r->filled('plant'))$b->where('e.plant',$r->input('plant'));$all=(clone $b);$open=(clone $b)->where('b.status','OPEN')->count();$started=(clone $b)->whereDate('b.start_time',now()->toDateString())->count();$closed=(clone $b)->whereDate('b.start_time',now()->toDateString())->where('b.status','CLOSED')->count();$closedToday=(clone $b)->whereDate('b.start_time',now()->toDateString())->where('b.status','CLOSED');$sum=(float)((clone $closedToday)->sum('b.downtime_minutes')?:0);$avg=(float)((clone $closedToday)->avg('b.downtime_minutes')?:0);$today=['open_breakdowns'=>$open,'started_today'=>$started,'closed_today'=>$closed,'total_downtime_today_min'=>$sum,'avg_mttr_min'=>$avg];$m=DB::table('breakdowns as b')->join('equipment as e','e.id','=','b.equipment_id')->where('b.start_time','>=',now()->subDays(30))->where('b.status','CLOSED');if($r->filled('plant'))$m->where('e.plant',$r->input('plant'));$cnt=(clone $m)->count();$down=(float)((clone $m)->sum('b.downtime_minutes')?:0);$mtbf=['breakdowns_30d'=>$cnt,'total_downtime_min_30d'=>$down,'mtbf_hours'=>$cnt?round((30*24*60-$down)/$cnt/60,1):null];return response()->json(['success'=>true,'data'=>['availability'=>$avail,'today'=>$today,'mtbf'=>$mtbf]]);}catch(Throwable $e){return $this->err($e);}}
 public function topReasons(Request $r){try{$days=(int)$r->input('days',30);$q=DB::table('breakdowns as b')->join('stop_reasons as sr','b.initial_reason_id','=','sr.id')->join('equipment as e','e.id','=','b.equipment_id')->select('sr.description','sr.category')->selectRaw('COUNT(*) AS count')->selectRaw('ROUND(SUM(b.downtime_minutes)) AS total_downtime_min')->where('b.start_time','>=',now()->subDays($days));if($r->filled('plant'))$q->where('e.plant',$r->input('plant'));return response()->json(['success'=>true,'data'=>$q->groupBy('sr.description','sr.category')->orderByDesc('count')->limit(10)->get()->all()]);}catch(Throwable $e){return $this->err($e);}}
 public function downtime(Request $r){try{$days=(int)$r->input('days',7);$q=DB::table('equipment as e')->leftJoin('breakdowns as b',function($j)use($days){$j->on('b.equipment_id','=','e.id')->where('b.start_time','>=',now()->subDays($days))->where('b.status','CLOSED');})->select('e.code','e.name','e.department','e.plant')->selectRaw('COUNT(b.id) AS breakdown_count, COALESCE(ROUND(SUM(b.downtime_minutes)),0) AS total_downtime_min, COALESCE(ROUND(AVG(b.downtime_minutes)),0) AS avg_downtime_min')->where('e.active',true);if($r->filled('plant'))$q->where('e.plant',$r->input('plant'));return response()->json(['success'=>true,'data'=>$q->groupBy('e.id','e.code','e.name','e.department','e.plant')->orderByDesc('total_downtime_min')->limit(20)->get()->all()]);}catch(Throwable $e){return $this->err($e);}}
 public function trend(Request $r){try{$days=(int)$r->input('days',14);$q=DB::table('breakdowns as b')->join('equipment as e','e.id','=','b.equipment_id')->selectRaw('DATE(b.start_time) AS day, COUNT(*) AS breakdowns, COALESCE(ROUND(SUM(b.downtime_minutes)),0) AS downtime_min')->where('b.start_time','>=',now()->subDays($days));if($r->filled('plant'))$q->where('e.plant',$r->input('plant'));return response()->json(['success'=>true,'data'=>$q->groupByRaw('DATE(b.start_time)')->orderBy('day')->get()->all()]);}catch(Throwable $e){return $this->err($e);}}
 public function departmentView(Request $r){try{$q=DB::table('equipment as e')->leftJoin('breakdowns as b','b.equipment_id','=','e.id')->select('e.department')->selectRaw("SUM(CASE WHEN b.status='OPEN' THEN 1 ELSE 0 END) AS open_breakdowns")->selectRaw("SUM(CASE WHEN b.status='CLOSED' AND DATE(b.start_time)=CURRENT_DATE THEN 1 ELSE 0 END) AS closed_today")->selectRaw("COALESCE(SUM(CASE WHEN DATE(b.start_time)=CURRENT_DATE AND b.status='CLOSED' THEN b.downtime_minutes ELSE 0 END),0) AS downtime_today_min")->selectRaw('COUNT(DISTINCT e.id) AS total_equipment')->selectRaw("SUM(CASE WHEN e.current_status='STOPPED' THEN 1 ELSE 0 END) AS equipment_stopped_now");if($r->filled('plant'))$q->where('e.plant',$r->input('plant'));return response()->json(['success'=>true,'data'=>$q->groupBy('e.department')->get()->all()]);}catch(Throwable $e){return $this->err($e);}}
 public function deptPerformance(Request $r){try{$dq=DB::table('equipment')->whereNotNull('department')->distinct()->orderBy('department');if($r->filled('plant'))$dq->where('plant',$r->input('plant'));$depts=$dq->pluck('department');$rows=[];foreach($depts as $d){$jq=DB::table('jobs')->where('assigned_dept',$d);if($r->filled('plant'))$jq->where('plant',$r->input('plant'));$open=(clone $jq)->whereIn('status',['OPEN','ASSIGNED','IN PROGRESS'])->count();$closedQ=(clone $jq)->where('status','CLOSED')->whereDate('closed_at',now()->toDateString());$closed=(clone $closedQ)->count();$avg=DB::table('jobs')->where('assigned_dept',$d)->when($r->filled('plant'),fn($q)=>$q->where('plant',$r->input('plant')))->where('status','CLOSED')->whereDate('closed_at',now()->toDateString())->whereNotNull('closed_at')->selectRaw('ROUND(AVG(TIMESTAMPDIFF(SECOND,created_at,closed_at)/60)) AS a')->value('a');$rows[]=['dept'=>$d,'open_jobs'=>$open,'closed_jobs'=>$closed,'avg_repair_min'=>(int)($avg?:0)];}return response()->json(['success'=>true,'data'=>$rows]);}catch(Throwable $e){return $this->err($e);}}
 public function shiftPerformance(Request $r){try{$rows=[];foreach(['A','B','C'] as $s){$i=DB::table('shift_monitoring_logs as sm')->join('equipment as e','e.id','=','sm.equipment_id')->whereDate('sm.logged_at',now()->toDateString())->where('sm.shift',$s);$d=DB::table('breakdowns as b')->join('shift_logs as sl','sl.id','=','b.shift_log_id')->join('equipment as e','e.id','=','b.equipment_id')->whereDate('b.start_time',now()->toDateString())->where('sl.shift',$s);$j=DB::table('jobs')->whereDate('created_at',now()->toDateString())->where('shift',$s);if($r->filled('plant')){$i->where('e.plant',$r->input('plant'));$d->where('e.plant',$r->input('plant'));$j->where('plant',$r->input('plant'));}$rows[]=['shift'=>$s,'inspections'=>$i->distinct()->count('sm.equipment_id'),'deviations'=>$d->count(),'jobs_created'=>$j->count()];}return response()->json(['success'=>true,'data'=>$rows]);}catch(Throwable $e){return $this->err($e);}}
 public function tpdComparison(){try{$plants=DB::table('equipment')->distinct()->orderBy('plant')->pluck('plant');$rows=[];foreach($plants as $p){$total=DB::table('equipment')->where('plant',$p)->count();$run=DB::table('equipment')->where('plant',$p)->where('current_status','RUNNING')->count();$dev=DB::table('breakdowns as b')->join('equipment as e','e.id','=','b.equipment_id')->where('e.plant',$p)->whereDate('b.start_time',now()->toDateString())->count();$jobs=DB::table('jobs')->where('plant',$p)->whereDate('created_at',now()->toDateString())->count();$rows[]=['plant'=>$p,'deviations'=>$dev,'jobs'=>$jobs,'efficiency'=>$total?round($run/$total*100,1):null];}return response()->json(['success'=>true,'data'=>$rows]);}catch(Throwable $e){return $this->err($e);}}
 private function err(Throwable $e){return response()->json(['success'=>false,'message'=>$e->getMessage()],500);}
}
